    if (!ctx || !ctx->memory || !handles_gva || !count) return;
    limit = count > ARRAY_SIZE(handles) ? ARRAY_SIZE(handles) : count;
    if (hb_memory_read( ctx->memory, (hb_gva_t)handles_gva, handles,
                        limit * sizeof(handles[0]) ) != HB_OK)
        return;
